// Real backend client — fetches `${REACT_APP_BACKEND_URL}/v1/*` endpoints.
// Endpoint paths + response adapters verified against the backend on 2026-04-21.
//
// Some response shapes differ from what the UI consumes; adapters here convert
// real-backend responses into the canonical UI shape (the same shape the mock
// client produces), so UI components don't need to know which backend they're
// talking to.

import { mockApi } from "./mockApi";
import { getAuthToken, logTokenFingerprintOnce } from "./authToken";
import { newIdempotencyKey } from "./idempotency";
import { getCurrentUserId } from "./currentUser";
import { chooseWorkspaceId, writeSelection } from "./workspaceSelection";
import { isPilotMode } from "./pilotMode";

const BASE = (process.env.REACT_APP_BACKEND_URL || "").replace(/\/+$/, "");

// Every workspace-scoped route types its path parameter as `uuid.UUID`, so a
// non-UUID is rejected by Pydantic before the handler runs:
//
//   GET /v1/workspaces/ws_acme_platform/analytics/overview
//   422 {"field":"path.workspace_id",
//        "message":"Input should be a valid UUID, invalid character: found `w` at 1",
//        "type":"uuid_parsing"}
//
// The previous default was the literal "ws_acme_platform" — a mock-shaped id
// that could never satisfy this API, so all ~16 workspace-scoped calls 422'd
// identically. Resolution order is now: explicit argument, configured env var,
// then the first workspace the signed-in user can actually see.
const CONFIGURED_WS = (process.env.REACT_APP_DEFAULT_WORKSPACE_ID || "").trim();



let _wsPromise = null;

// Bumped on every identity change. Two jobs:
//
//   1. A lookup abandoned by an identity change must not write back into the
//      module after the fact. Its `.catch` would otherwise null out the NEW
//      user's in-flight memo (see resolveWorkspaceId), so the generation is
//      captured when the memo is created and re-checked before clearing it.
//   2. It gives the React layer something to subscribe to, so mounted screens
//      can drop the previous identity's rendered rows and invalidate requests
//      already on the wire. Clearing `_wsPromise` alone does neither: it only
//      affects lookups that have not started yet.
let _identityGeneration = 0;
const _identityListeners = new Set();

/** Current identity generation. Changes iff the signed-in user changed. */
export function identityGeneration() {
    return _identityGeneration;
}

/**
 * Subscribe to identity changes. Returns an unsubscribe function.
 *
 * Listeners are called synchronously from resetIdentityScopedCaches, so a
 * subscriber can invalidate in-flight work before any newly issued request
 * has a chance to resolve.
 */
export function onIdentityReset(listener) {
    _identityListeners.add(listener);
    return () => _identityListeners.delete(listener);
}

/**
 * Drop every cached, identity-scoped value.
 *
 * `_wsPromise` memoises the workspace UUID for the whole module lifetime. That
 * is correct for one signed-in user and wrong the instant the user changes: B
 * would inherit A's workspace id and every scoped request would be issued
 * against a workspace B may not belong to. The API would answer 404 (the
 * isolation gate does its job), but the UI would be asking the wrong question
 * and would report "not available" rather than showing B's own data.
 *
 * Today a sign-out is a full document navigation, so module state is discarded
 * anyway — see the note in ClerkAuthBridge. This exists so that correctness
 * does not DEPEND on that: it is a property of Clerk's navigation mode, not
 * something this app states or controls, and adding routerPush/routerReplace
 * (the ordinary Clerk + React Router integration) would silently remove it.
 */
/**
 * The workspace a request would be scoped to, resolved once.
 *
 * Exported so a caller can resolve the workspace ITSELF and then use the same
 * value twice — for the idempotency-key identity and for the request — instead
 * of letting the adapter resolve independently. Two resolutions could differ
 * across an identity change, and a key chosen against one workspace while the
 * request goes to another is precisely the mismatch the key is meant to rule
 * out.
 */
export async function resolveWorkspace(explicit) {
    return resolveWorkspaceId(explicit);
}

// ---------- workspace scope ----------
//
// Switching workspace is the same hazard as switching user, one level down: a
// response issued for workspace A must never be stored or rendered once the
// user is in B. Clearing caches is not enough — requests already on the wire
// still resolve. So every workspace-scoped request captures the scope
// generation when it starts and carries an AbortSignal; a response (or
// failure) that lands after the generation moved is DROPPED by throwing a
// StaleWorkspaceError, which callers ignore silently.
//
// The generation also moves on an identity change (a different user is a
// different scope), and both events use the one listener registry above, so
// every existing subscriber (useApiResource, Conflicts) is told with no new
// wiring. Listeners receive (identityGeneration, kind) where kind is
// "identity" or "workspace".
let _workspaceGeneration = 0;
let _abort = new AbortController();
// The choice made this session, bound to the user who made it.
let _selected = null;

export class StaleWorkspaceError extends Error {
    constructor() {
        super("Workspace changed while this request was in flight");
        this.name = "StaleWorkspaceError";
        this.stale = true;
    }
}

export const isStaleWorkspaceError = (err) => Boolean(err && err.stale === true);

/** True when the build fixes the workspace (REACT_APP_DEFAULT_WORKSPACE_ID). */
export function isWorkspacePinned() {
    return Boolean(CONFIGURED_WS);
}

/** Current workspace-scope generation. Moves on any workspace or identity change. */
export function workspaceGeneration() {
    return _workspaceGeneration;
}

/** Same registry as onIdentityReset; named for what the caller cares about. */
export function onWorkspaceScopeChange(listener) {
    return onIdentityReset(listener);
}

function advanceScope(kind) {
    _workspaceGeneration += 1;
    _wsPromise = null;
    // Abort everything still on the wire for the old scope.
    const old = _abort;
    _abort = new AbortController();
    try {
        old.abort();
    } catch {
        // Aborting is best effort; the generation check is the real guard.
    }
    // Copy first: a listener may unsubscribe itself while being notified.
    for (const listener of Array.from(_identityListeners)) {
        try {
            listener(_identityGeneration, kind);
        } catch {
            // A broken subscriber must not stop the others from being told the
            // scope changed — that is the failure mode this exists to stop.
        }
    }
}

export function resetIdentityScopedCaches() {
    _identityGeneration += 1;
    _selected = null;
    advanceScope("identity");
}

/**
 * Make `workspaceId` the current workspace. Persists the choice for this user
 * (best effort), invalidates in-flight work and notifies subscribers.
 */
export function selectWorkspace(workspaceId) {
    // A build pinned to one workspace sends every request there; a selection
    // would only make the UI claim otherwise.
    if (!workspaceId || CONFIGURED_WS) return;
    const userId = getCurrentUserId();
    _selected = { userId, id: workspaceId };
    writeSelection(userId, workspaceId);
    mockApi.selectWorkspace(workspaceId);
    advanceScope("workspace");
}

/**
 * The workspace UUID to scope requests to.
 *
 * The lookup is memoised as a promise, not a value, so concurrent callers on
 * first paint share one request instead of each firing their own. A failure
 * clears the memo so the next attempt retries rather than caching the error.
 */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

async function resolveWorkspaceId(explicit) {
    // An explicit id is honoured only if it could actually satisfy the route.
    // Several pages still pass mock-era placeholders — Dashboard.jsx sent
    // "ws_acme_platform", Analytics/Conflicts/Connectors/Handoff send "ws" —
    // which mockApi ignored entirely but which the real API rejects with a 422
    // before the handler runs. Falling through is strictly better than
    // forwarding a value that cannot work.
    if (explicit) {
        if (UUID_RE.test(explicit)) return explicit;
        if (process.env.NODE_ENV !== "production") {
            // eslint-disable-next-line no-console
            console.warn(
                `[SourceMind] Ignoring non-UUID workspace id ${JSON.stringify(explicit)} ` +
                "— falling back to the configured/resolved workspace."
            );
        }
    }
    if (CONFIGURED_WS) return CONFIGURED_WS;

    // The scope this resolution belongs to. If it moves while the lookup is in
    // flight the answer is for the old scope and must not be handed out.
    const startedIn = _workspaceGeneration;
    if (!_wsPromise) {
        // Captured with the memo, checked before the memo is cleared below.
        const generation = _workspaceGeneration;
        // Whose lookup this is. The selection read/validated/cleared below is
        // THIS user's, even if someone else has signed in by the time the
        // answer arrives; otherwise A's list would be used to judge (and
        // delete) B's saved choice.
        const lookupUser = getCurrentUserId();
        const lookupIdentity = _identityGeneration;
        _wsPromise = request("/v1/workspaces", { scoped: false })
            .then((r) => {
                if (lookupIdentity !== _identityGeneration) throw new StaleWorkspaceError();
                // This route IS enveloped: {data: [...], meta: {...}}.
                const list = Array.isArray(r.data) ? r.data : [];
                if (!list.length) {
                    throw new ApiError(
                        404,
                        "This account has no workspaces. Create one, or ask a " +
                        "workspace owner to add you.",
                        r
                    );
                }
                const userId = lookupUser;
                const preferred = _selected && _selected.userId === userId ? _selected.id : null;
                return chooseWorkspaceId(list, userId, preferred);
            })
            .catch((err) => {
                // Only clear the memo if it is still the one this lookup
                // created. If the user changed while this was in flight, the
                // memo now belongs to the NEW user's lookup, and nulling it
                // here would discard a live request and force a duplicate.
                // A failure is the likely case, not a rare one: the previous
                // user's token is gone, so this call typically ends in 401.
                if (generation === _workspaceGeneration) _wsPromise = null;
                throw err;
            });
    }
    const id = await _wsPromise;
    if (startedIn !== _workspaceGeneration) throw new StaleWorkspaceError();
    return id;
}

// Deterministic palette — used when the backend doesn't include a color.
const PALETTE = ["#4F7EFF", "#A78BFA", "#34D399", "#F59E0B", "#EF4444", "#60A5FA", "#F472B6", "#2DD4BF"];
const colorFor = (key, i = 0) => {
    if (typeof i === "number" && i >= 0) return PALETTE[i % PALETTE.length];
    const s = String(key || "");
    let h = 0;
    for (let k = 0; k < s.length; k++) h = (h * 31 + s.charCodeAt(k)) | 0;
    return PALETTE[Math.abs(h) % PALETTE.length];
};

// Activity colour coding.
//
// This map was written against mockData, not against the API, and none of its
// original eight keys could ever match. The feed is built by get_overview from
// a single query over `attribution_edits`, so `action` is always one of the
// five AttributionActionType members - create, edit, approve, reject, merge -
// and every real event fell through to the default blue.
//
// The removed keys were not merely misspelled. conflict_opened,
// conflict_detected, conflict_resolved, connector_synced, handoff_started and
// handoff_initiated describe events this endpoint STRUCTURALLY cannot emit:
// nothing in the query touches memory_conflicts, connector_sync_logs or
// handoff_records. They encoded a unified multi-source activity feed that does
// not exist on the backend. Restoring them means changing get_overview, not
// this file.
//
// The mock vocabulary is kept alongside so the offline demo still renders in
// colour; mockData emits `type:` while the API emits `action`, and
// adaptOverview already reads `a.action || a.type`.
export const ACTION_COLOR = {
    // Real: AttributionActionType (attribution_edits.action_type)
    create:            "#4F7EFF",  // sm-blue
    edit:              "#4F7EFF",  // sm-blue
    approve:           "#34D399",  // sm-green
    reject:            "#EF4444",  // sm-red
    merge:             "#A78BFA",  // sm-purple

    // Mock-only, retained for REACT_APP_USE_MOCKS=true.
    memory_created:    "#4F7EFF",
    memory_edited:     "#4F7EFF",
    conflict_opened:   "#F59E0B",
    conflict_resolved: "#34D399",
    connector_synced:  "#34D399",
    handoff_started:   "#A78BFA",
};

class ApiError extends Error {
    constructor(status, message, body, { retryAfterSeconds = null, network = false } = {}) {
        super(message);
        this.status = status;
        this.body = body;
        // Populated from the Retry-After response header on a 429. The backend
        // limiter is fail-closed, so a client that retries immediately makes
        // the situation worse; the UI needs the server's own number.
        this.retryAfterSeconds = retryAfterSeconds;
        // True when fetch() itself rejected — DNS failure, offline, CORS,
        // connection refused. There is no status in that case, and it is not
        // the same condition as a 5xx, which proves the server was reached.
        this.network = network;
    }
}

/** Retry-After is either delta-seconds or an HTTP-date (RFC 9110 §10.2.3). */
function parseRetryAfter(raw) {
    if (!raw) return null;
    const seconds = Number(raw);
    if (Number.isFinite(seconds)) return seconds >= 0 ? Math.ceil(seconds) : null;
    const when = Date.parse(raw);
    if (Number.isNaN(when)) return null;
    return Math.max(0, Math.ceil((when - Date.now()) / 1000));
}

// `scoped` (default true): the request belongs to the current workspace scope.
// It is aborted, and its outcome discarded as stale, if the scope changes
// before it settles. Requests about the USER rather than a workspace (who am
// I, list my workspaces, create a workspace, add a member) pass scoped:false.
async function request(path, { method = "GET", body, params, headers: extraHeaders, scoped = true } = {}) {
    // Captured synchronously, before the first await: callers resolve the
    // workspace id (which itself verifies the scope) and call straight in.
    const startedIn = _workspaceGeneration;
    const signal = scoped ? _abort.signal : undefined;
    const isStale = () => scoped && startedIn !== _workspaceGeneration;
    const url = new URL(BASE + path, window.location.origin);
    if (params) {
        for (const [k, v] of Object.entries(params)) {
            if (v !== undefined && v !== null) url.searchParams.set(k, String(v));
        }
    }
    // Every backend route except /health is behind get_current_user, which
    // verifies a Clerk JWT against the instance JWKS. Without this header the
    // API answers 401 SM001 ("Authorization header required").
    //
    // Fetched per request, not cached: Clerk session tokens expire in about a
    // minute and getToken() refreshes them transparently.
    const token = await getAuthToken();
    if (token) logTokenFingerprintOnce(token);

    const headers = {
        "Content-Type": "application/json",
        Accept: "application/json",
        ...extraHeaders,
    };
    if (token) headers.Authorization = `Bearer ${token}`;

    // The scope may have moved while the token was being fetched; do not send
    // a request that is already for the wrong workspace.
    if (isStale()) throw new StaleWorkspaceError();

    const t0 = performance.now();
    let res;
    try {
        res = await fetch(url.toString(), {
            method,
            credentials: "include",
            headers,
            body: body ? JSON.stringify(body) : undefined,
            ...(signal ? { signal } : {}),
        });
    } catch (cause) {
        // An abort caused by a scope change is not a network failure.
        if (isStale() || (cause && cause.name === "AbortError" && signal)) {
            throw new StaleWorkspaceError();
        }
        // fetch() rejects only on a transport failure. Surfacing it as an
        // ApiError with network:true lets callers tell "could not reach the
        // API" apart from "the API answered with an error", which need
        // different wording and different retry behaviour.
        throw new ApiError(0, cause?.message || "Network request failed", null, {
            network: true,
        });
    }
    const latency = Math.round(performance.now() - t0);
    let text;
    try {
        text = await res.text();
    } catch (cause) {
        // A switch can abort the body while it is still being read.
        if (isStale() || (cause && cause.name === "AbortError" && signal)) {
            throw new StaleWorkspaceError();
        }
        throw cause;
    }
    // The response is for a workspace the user has left: drop it unread.
    if (isStale()) throw new StaleWorkspaceError();
    const data = text ? JSON.parse(text) : {};
    if (!res.ok) {
        throw new ApiError(res.status, `${res.status} ${res.statusText}`, data, {
            retryAfterSeconds: parseRetryAfter(res.headers.get("Retry-After")),
        });
    }
    return { ...data, __latency_ms: latency };
}

// ---------- response envelope ----------
//
// The API is NOT uniform, and both directions matter: unwrapping a raw
// response is as wrong as failing to unwrap an enveloped one. Routes declared
// `response_model=APIResponse[T]` return {data, meta}; everything else returns
// its payload at the top level. Verified endpoint by endpoint against the
// running API rather than inferred:
//
//   ENVELOPED  /v1/team/me, /v1/workspaces, /v1/workspaces/{ws},
//              /v1/workspaces/{ws}/members, /v1/memories/{id},
//              POST /v1/memories, /v1/memories/jobs/{id}
//   RAW        all four /analytics/*, /conflicts, /connectors, /handoffs,
//              POST /v1/memories/search
//
// Only the ENVELOPED list goes through these helpers.

/** {data: {...}, meta} -> {...} , preserving the measured latency. */
function unwrapOne(r) {
    const d = r && r.data;
    if (d && typeof d === "object" && !Array.isArray(d)) {
        return { ...d, __latency_ms: r.__latency_ms };
    }
    return r;
}

/** {data: [...], meta} -> the array, preserving the measured latency. */
function unwrapList(r) {
    return {
        items: Array.isArray(r && r.data) ? r.data : [],
        __latency_ms: r && r.__latency_ms,
    };
}

// ---------- adapters ----------

function adaptOverview(r) {
    // Backend returns health_breakdown values as decimals (0.0–1.0) with key
    // `attribution`; the UI wants percentages (0–100) with key `attribution_coverage`.
    const hb = r.health_breakdown || {};
    const toPct = (v) => (v == null ? 0 : Math.round(v * 100));
    const health_breakdown = {
        coverage:             toPct(hb.coverage),
        freshness:            toPct(hb.freshness),
        conflict_ratio:       toPct(hb.conflict_ratio),
        attribution_coverage: toPct(hb.attribution ?? hb.attribution_coverage),
    };

    // top_contributors: {user_id, name, memory_count, avg_contribution_pct} →
    //                   {name, count, color}
    const top_contributors = (r.top_contributors || []).map((c, i) => ({
        name:  c.name,
        count: c.memory_count ?? c.count ?? 0,
        color: colorFor(c.user_id || c.name, i),
    }));

    // recent_activity: backend now returns `description` directly.
    // We keep the `action` field to drive color coding.
    const recent_activity = (r.recent_activity || []).map((a) => ({
        type:        a.action || a.type || "memory_created",
        description: a.description || "",
        color:       ACTION_COLOR[a.action] || "#4F7EFF",
        timestamp:   a.timestamp,
    }));

    // knowledge_health_score is a 0.0-1.0 fraction, like the breakdown values,
    // but the UI renders it out of 100 in two places: the page subtitle
    // ("health {score}/100") and HealthGauge, which animates Math.round(score)
    // straight onto a /100 dial. Converting the breakdown while leaving this
    // raw is what produced "health 0.25/100" beside a gauge reading 0.
    // mockApi already returns this on a 0-100 scale, so converting here also
    // makes the two clients agree.
    const knowledge_health_score = toPct(r.knowledge_health_score);

    return {
        ...r,
        knowledge_health_score,
        health_breakdown,
        top_contributors,
        recent_activity,
    };
}

/**
 * ContributionBreakdown[] -> the shape MemoryDetail renders.
 *
 * Backend: {user: {id, display_name, avatar_url}, contribution_weight,
 *           percentage, signals, is_primary}
 * UI:      {author, name, score, percentage, is_primary, color, signals}
 *
 * Two fields have no real equivalent and must not be faked:
 *   - there is no login handle; UserSummary carries id/display_name/avatar_url
 *     only, so `author` falls back to the display name.
 *   - `signals` is null unless the caller is owner/admin, so the per-signal
 *     column has to tolerate its absence rather than assume five numbers.
 */
function adaptAttribution(list) {
    if (!Array.isArray(list)) return [];
    return list.map((a, i) => ({
        author: a.user?.display_name || a.user?.id || "unknown",
        name: a.user?.display_name || null,
        avatar_url: a.user?.avatar_url || null,
        score:
            a.contribution_weight ??
            (a.percentage != null ? a.percentage / 100 : 0),
        percentage: a.percentage ?? null,
        is_primary: Boolean(a.is_primary),
        color: colorFor(a.user?.id || a.user?.display_name, i),
        signals: a.signals || null,
    }));
}

function adaptKnowledgeGap(gap) {
    return {
        ...gap,
        affected_count: gap.affected_count ?? gap.affected_memories ?? 0,
        recommended_action: gap.recommended_action ?? gap.recommendation ?? "",
    };
}

function adaptContributor(c, i) {
    // Backend shape:
    //   {user_id, login, name, total_memories_created, total_memories_influenced,
    //    avg_contribution_pct, collaboration_rate, last_contribution_at}
    // avg_contribution_pct may arrive as either 0–1 or 0–100; normalise to 0–1.
    const pct = c.avg_contribution_pct ?? c.score ?? 0;
    return {
        id:           c.user_id || c.id,
        login:        c.login,
        name:         c.name,
        count:        c.total_memories_influenced ?? c.total_memories_created ?? c.count ?? 0,
        score:        pct > 1 ? pct / 100 : pct,
        last_active:  c.last_contribution_at || c.last_active || null,
        avatarColor:  colorFor(c.user_id || c.login, i),
        top_category: "",
    };
}

// ---------- public client ----------

export const realApi = {
    // ----- session -----
    getCurrentUser: async () => unwrapOne(await request(`/v1/team/me`, { scoped: false })),

    // ----- workspaces -----
    // GET /v1/workspaces is enveloped: {data: [...], meta}. Not workspace
    // scoped (it is how the scope is chosen), so it is never aborted by a switch.
    listWorkspaces: async () => {
        const r = unwrapList(await request(`/v1/workspaces`, { scoped: false }));
        return { items: r.items, __latency_ms: r.__latency_ms };
    },
    // The backend does NOT de-duplicate on the key, so the caller must guard
    // against double submits; the key is still required (UUIDv4).
    createWorkspace: async ({ name, slug, description } = {}) =>
        unwrapOne(
            await request(`/v1/workspaces`, {
                method: "POST",
                scoped: false,
                headers: { "Idempotency-Key": newIdempotencyKey() },
                body: {
                    name,
                    slug,
                    ...(description ? { description } : {}),
                },
            })
        ),
    // Owner/admin only. `role` is member or viewer; the backend rejects
    // anything else and any extra field.
    addWorkspaceMember: async (workspaceId, { email, role = "member" } = {}) =>
        unwrapOne(
            await request(`/v1/workspaces/${encodeURIComponent(workspaceId)}/members`, {
                method: "POST",
                scoped: false,
                headers: { "Idempotency-Key": newIdempotencyKey() },
                body: { email, role },
            })
        ),
    getWorkspace: async (wsId) =>
        unwrapOne(await request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}`)),

    // ----- analytics -----
    // These four routes return a RAW dict, not the {data, meta} envelope used
    // by /v1/team/me and /v1/workspaces, so the adapters read fields straight
    // off the response. Verified against the deployed API.
    getAnalyticsOverview: async (wsId) => {
        const ws = await resolveWorkspaceId(wsId);
        const r = await request(`/v1/workspaces/${ws}/analytics/overview`);
        return adaptOverview(r);
    },
    getKnowledgeGaps: async (wsId) => {
        const response = await request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/analytics/knowledge-gaps`);
        return {
            ...response,
            gaps: Array.isArray(response.gaps) ? response.gaps.map(adaptKnowledgeGap) : [],
        };
    },
    getContributionMap: async (wsId) => {
        const ws = await resolveWorkspaceId(wsId);
        const r = await request(`/v1/workspaces/${ws}/analytics/contribution-map`);
        const contributors = (r.contributors || []).map(adaptContributor);
        return { ...r, contributors };
    },
    // These two endpoints don't exist on the backend yet — fall back to mock
    // data so the Analytics page still renders. Remove once backend ships
    // `/analytics/memories-over-time` and `/analytics/search-activity`.
    getMemoriesOverTime: (wsId) => mockApi.getMemoriesOverTime(wsId),
    getSearchActivity:   (wsId) => mockApi.getSearchActivity(wsId),

    // ----- memories -----
    // workspace_id is a QUERY parameter, singular, typed UUID:
    //
    //   workspace_id: UUID = Query(default=_DEV_WORKSPACE_ID, ...)
    //   effective_ws_id = current_user.workspace_id or workspace_id
    //
    // SearchRequest declares only {query, mode, limit, min_similarity,
    // include_attribution, filters} — there is no workspace_ids field, so the
    // array this used to put in the body was dropped by Pydantic and the route
    // fell through to its default, _DEV_WORKSPACE_ID
    // (00000000-0000-4000-8000-000000000010). Search returned HTTP 200 with
    // real-looking results from the Dev Workspace instead of the user's.
    //
    // current_user.workspace_id is never assigned in the auth path — it stays
    // None — so the query parameter is what actually decides, and omitting it
    // silently searches the wrong workspace rather than erroring.
    searchMemories: async ({
        query = "",
        mode = "hybrid",
        limit = 20,
        workspace_id,
        include_attribution = false,
        // Source link / authorship / staleness. Asked for in normal mode only:
        // the pilot search body must stay exactly {query, mode, limit}.
        include_source = !isPilotMode(),
    } = {}) => {
        const response = await request(`/v1/memories/search`, {
            method: "POST",
            params: { workspace_id: await resolveWorkspaceId(workspace_id) },
            // Only sent when asked for: the pilot search must stay exactly
            // {query, mode, limit}, and attribution adds latency.
            body: {
                query, mode, limit,
                ...(include_attribution ? { include_attribution: true } : {}),
                ...(include_source ? { include_source: true } : {}),
            },
        });
        if (!include_attribution || !Array.isArray(response?.results)) return response;
        // Same adapter as the detail page. Anything absent stays absent: a
        // result with no attribution renders no attribution, not a guess.
        return {
            ...response,
            results: response.results.map((item) =>
                item?.memory && Array.isArray(item.memory.attribution)
                    ? { ...item, memory: { ...item.memory, attribution: adaptAttribution(item.memory.attribution) } }
                    : item
            ),
        };
    },
    // include_attribution must be asked for explicitly — it defaults to false,
    // and MemoryDetail renders the breakdown as a primary element of the page.
    getMemory: async (id) => {
        const r = unwrapOne(
            await request(`/v1/memories/${encodeURIComponent(id)}`, {
                params: { include_attribution: true },
            })
        );
        return { ...r, attribution: adaptAttribution(r.attribution) };
    },
    // workspace_id is set AFTER the spread so a caller cannot silently
    // override it with a placeholder — the previous order let Memories.jsx's
    // hardcoded "ws_acme_platform" win. A caller that genuinely wants another
    // workspace passes a real UUID, which resolveWorkspaceId honours.
    /**
     * POST /v1/memories, matched to the signature the route actually declares:
     *
     *     workspace_id: UUID = Query(...)    REQUIRED query parameter
     *     idempotency_key: IdempotencyKey    REQUIRED header, parsed as UUID v4
     *
     * This previously sent workspace_id in the BODY and no header, so every
     * ingestion was rejected before the handler ran — 422 for the missing
     * query parameter, and InvalidIdempotencyKeyError for the missing header.
     * The adapter read perfectly sensibly on its own; only the route's
     * signature shows it was wrong, which is why apiContract.test.js pins it.
     */
    createMemory: async ({ workspace_id, idempotencyKey, ...payload } = {}) =>
        unwrapOne(
            await request(`/v1/memories`, {
                method: "POST",
                params: { workspace_id: await resolveWorkspaceId(workspace_id) },
                // A caller RETRYING the same logical submission passes the key
                // it already sent, so the backend can recognise the repeat
                // instead of ingesting the content twice. Only a caller with
                // no key gets a fresh one — a key minted per call would make
                // every retry a new submission, which is the opposite of what
                // the header is for.
                headers: { "Idempotency-Key": idempotencyKey || newIdempotencyKey() },
                body: payload,
            })
        ),
    updateMemory: async (id, { idempotencyKey, ...payload } = {}) =>
        unwrapOne(
            await request(`/v1/memories/${encodeURIComponent(id)}`, {
                method: "PATCH",
                headers: { "Idempotency-Key": idempotencyKey || newIdempotencyKey() },
                body: payload,
            })
        ),
    getJobStatus: async (jobId) => {
        const r = unwrapOne(
            await request(`/v1/memories/jobs/${encodeURIComponent(jobId)}`)
        );
        // Normalise the terminal state to the vocabulary the UI polls for.
        return { ...r, status: r.status === "completed" ? "done" : r.status };
    },
    // Also available on the backend:
    //   PATCH  /v1/memories/{id}, DELETE /v1/memories/{id},
    //   GET    /v1/memories/{id}/versions, /attribution, /edits

    // ----- conflicts -----
    listConflicts: async (wsId, { status = "all", cursor = null } = {}) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/conflicts`, {
            params: { status, cursor },
        }),
    // GET /v1/memories/{id}/versions -> MemoryVersionsResponse
    //   { versions: [{id, version, is_current, content, created_at}], total }
    //
    // Declared with `response_model=MemoryVersionsResponse`, NOT
    // `APIResponse[T]`, so the payload is raw and must not be unwrapped.
    // Guarded by require_memory_access, so a non-member gets 404 rather than
    // an empty list — the caller has to tell those apart.
    getMemoryVersions: async (id) =>
        request(`/v1/memories/${encodeURIComponent(id)}/versions`),

    createPilotRating: async ({ workspace_id, idempotencyKey, ...payload } = {}) =>
        unwrapOne(
            await request(
                `/v1/workspaces/${await resolveWorkspaceId(workspace_id)}/pilot-ratings`,
                {
                    method: "POST",
                    headers: { "Idempotency-Key": idempotencyKey || newIdempotencyKey() },
                    body: payload,
                }
            )
        ),
    getPilotExport: async (wsId) =>
        unwrapOne(
            await request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/pilot-export`)
        ),

    getConflict: (id) => request(`/v1/conflicts/${encodeURIComponent(id)}`),
    reviewConflict: (id) =>
        request(`/v1/conflicts/${encodeURIComponent(id)}/review`, { method: "POST" }),
    // ResolveBody declares {resolution_type, resolution_note, merged_content,
    // revisit_at, tag_a, tag_b}. This sent `note`, which Pydantic silently
    // dropped — the field simply is not on the model — so every resolution
    // note the user typed was discarded without any error. The value reaches
    // `resolution_note = :note` in resolver.py once the key is right.
    //
    // `note` is still accepted as the caller-facing argument name so existing
    // call sites keep working; only the wire key changes.
    // ResolveBody: {resolution_type, resolution_note, merged_content,
    // revisit_at, tag_a, tag_b}. Only the fields the chosen action needs are
    // sent; the rest stay absent rather than being sent as null, so a typo in
    // an action name cannot look like a deliberate empty value.
    //
    // revisit_at must carry an offset: memory_conflicts.revisit_at is
    // TIMESTAMP(timezone=True), and resolver.py binds the parsed datetime
    // straight through to asyncpg. A naive local string would be stored as
    // though it were UTC and the conflict would resurface at the wrong hour.
    // The caller passes an ISO-8601 UTC instant.
    resolveConflict: (id, {
        resolution_type,
        note,
        merged_content,
        revisit_at,
        tag_a,
        tag_b,
    } = {}) => {
        const body = { resolution_type, resolution_note: note ?? null };
        if (merged_content !== undefined) body.merged_content = merged_content;
        if (revisit_at !== undefined) body.revisit_at = revisit_at;
        if (tag_a !== undefined) body.tag_a = tag_a;
        if (tag_b !== undefined) body.tag_b = tag_b;
        return request(`/v1/conflicts/${encodeURIComponent(id)}/resolve`, {
            method: "POST",
            body,
        });
    },

    // ----- connectors -----
    listConnectors: async (wsId) => {
        const r = await request(
            `/v1/workspaces/${await resolveWorkspaceId(wsId)}/connectors`
        );
        return { ...r, connectors: r.items || r.connectors || [] };
    },
    createConnector: async (wsId, payload) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/connectors`, {
            method: "POST",
            body: payload,
        }),
    getConnector: (id) => request(`/v1/connectors/${encodeURIComponent(id)}`),
    // PATCH {status: "paused"|"active"} / {display_name}
    updateConnector: (id, payload) =>
        request(`/v1/connectors/${encodeURIComponent(id)}`, { method: "PATCH", body: payload }),
    // 200 with a DisconnectResponse body (not 204). remove_memories is sent
    // explicitly in both cases so the choice is always on the wire.
    deleteConnector: (id, { remove_memories = false } = {}) =>
        request(`/v1/connectors/${encodeURIComponent(id)}`, {
            method: "DELETE",
            params: { remove_memories: remove_memories ? "true" : "false" },
        }),
    // 202. An explicit body: the route declares a required request model.
    triggerSync: (connId, { sync_type = "incremental" } = {}) =>
        request(`/v1/connectors/${encodeURIComponent(connId)}/sync`, {
            method: "POST",
            body: { sync_type },
        }),
    // ConnectorStatusResponse (state, scopes, documents, filtered, current_run, recent_logs)
    getConnectorStatus: (connId) =>
        request(`/v1/connectors/${encodeURIComponent(connId)}/status`),
    // GitHubInsightsResponse: stored activity only; no live provider request.
    getGithubInsights: async (wsId, params = {}) =>
        request(
            `/v1/workspaces/${await resolveWorkspaceId(wsId)}/connectors/github/insights`,
            { params }
        ),
    // MCP keys (K1). create returns the secret ONCE in `key`; list never contains it.
    listMcpKeys: async (wsId) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/mcp-keys`),
    createMcpKey: async (wsId, { name, expires_in_days = 90 }) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/mcp-keys`, {
            method: "POST",
            body: { name, expires_in_days },
        }),
    // 204 No Content (unknown or not-yours -> 404).
    revokeMcpKey: async (wsId, keyId) =>
        request(
            `/v1/workspaces/${await resolveWorkspaceId(wsId)}/mcp-keys/${encodeURIComponent(keyId)}`,
            { method: "DELETE" }
        ),
    retryFailedConnector: (connId) =>
        request(`/v1/connectors/${encodeURIComponent(connId)}/retry-failed`, { method: "POST" }),
    rescanConnector: (connId) =>
        request(`/v1/connectors/${encodeURIComponent(connId)}/rescan`, { method: "POST" }),
    // 202 RearmQuarantinedResponse {connector_id, rearmed, scopes_marked, message}
    rearmQuarantined: (connId) =>
        request(`/v1/connectors/${encodeURIComponent(connId)}/rearm-quarantined`, { method: "POST" }),
    // SyncLogsResponse: {items: SyncLogResponse[], total}
    getSyncLogs: (connId, { limit = 20, offset = 0 } = {}) =>
        request(`/v1/connectors/${encodeURIComponent(connId)}/sync-logs`, {
            params: { limit, offset },
        }),
    // GitHub connect flow. The browser navigates to authorize_url; the callback
    // page then redeems code+state. User-scoped, not workspace-scoped: the
    // workspace comes from the signed state on the server.
    authorizeGithub: async (wsId) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/connectors/github/authorize`),
    completeGithubCallback: ({ code, state, installation_id } = {}) =>
        request(`/v1/connectors/github/callback`, {
            method: "POST",
            scoped: false,
            body: { code, state, ...(installation_id ? { installation_id } : {}) },
        }),
    // POST /v1/memories/{retired}/reapply -> APIResponse[MemoryResponse]
    reapplyMemory: async (retiredId, { idempotencyKey, ...payload } = {}) =>
        unwrapOne(
            await request(`/v1/memories/${encodeURIComponent(retiredId)}/reapply`, {
                method: "POST",
                headers: { "Idempotency-Key": idempotencyKey || newIdempotencyKey() },
                body: payload,
            })
        ),

    // ----- handoffs -----
    //
    // NOT a /team route. handoff_router is declared `APIRouter(tags=["handoff"])`
    // with no prefix and mounted at /v1, so the real paths are
    // /v1/workspaces/{id}/handoff/{initiate,assign,complete}. The previous
    // /v1/team/... URLs 404'd. (listHandoffs below was already correct.)
    //
    // The field names were wrong too, so fixing only the path would have turned
    // a 404 into a 422: InitiateHandoffBody accepts exactly
    // {departing_user_id}, while the page and mockApi both speak
    // `departing_id`. receiving_id / departure_date / notes are not part of the
    // initiate contract at all — the backend classifies memories for the
    // departing user and the receiver is chosen later, per-memory, via assign.
    // They are dropped here rather than sent and silently ignored.
    //
    // Returns: { handoff_record_id, departing_user_id, departing_user_name,
    //            total_memories,
    //            tier_1_critical: [{memory_id, content, importance_score,
    //                               suggested_successor_id,
    //                               suggested_successor_name,
    //                               successor_confidence}],
    //            tier_2_important: [{memory_id, content, importance_score}],
    //            tier_3_standard_count }
    classifyHandoff: async ({ departing_id, wsId } = {}) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/handoff/initiate`, {
            method: "POST",
            body: { departing_user_id: departing_id },
        }),

    // AssignHandoffBody: {memory_id, new_owner_id, handoff_record_id, note?}
    assignHandoff: async (wsId, payload) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/handoff/assign`, {
            method: "POST",
            body: payload,
        }),

    // CompleteHandoffBody: {departing_user_id, handoff_record_id}
    completeHandoff: async (wsId, payload) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/handoff/complete`, {
            method: "POST",
            body: payload,
        }),
    listHandoffs: async (wsId) =>
        request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/handoffs`),

    // GET /v1/workspaces/:id/analytics/who-would-know?q=<query>
    whoWouldKnow: async (wsId, { q = "", limit = 5 } = {}) => {
        const ws = await resolveWorkspaceId(wsId);
        const r = await request(`/v1/workspaces/${ws}/analytics/who-would-know`, {
            params: { q, limit },
        });
        // Attach colors not returned by the backend
        const experts = (r.experts || []).map((e, i) => ({
            ...e,
            avatarColor: colorFor(e.user_id || e.login, i),
        }));
        return { ...r, experts };
    },

    // ----- team / contributors -----
    listTeamMembers: async (wsId) => {
        const r = unwrapList(
            await request(`/v1/workspaces/${await resolveWorkspaceId(wsId)}/members`)
        );
        return { members: r.items, __latency_ms: r.__latency_ms };
    },
    listContributors: async (wsId) => {
        const ws = await resolveWorkspaceId(wsId);
        const r = await request(`/v1/workspaces/${ws}/analytics/contribution-map`);
        const contributors = (r.contributors || []).map(adaptContributor);
        return { contributors, __latency_ms: r.__latency_ms };
    },
};

export default realApi;
export { ApiError, parseRetryAfter };
